import { booleanAttribute, ChangeDetectionStrategy, Component, input } from "@angular/core";

@Component({
    selector: "app-card",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<section class="card" [attr.title]="disableTooltip() ? null : heading()"><h3>{{ heading() }}</h3><ng-content /></section>`
})
export class CardComponent {
    readonly heading = input("");
    /** disableTooltip: the card shows no title hint. */
    readonly disableTooltip = input(false, { transform: booleanAttribute });
}
--- legacy ---
import { ChangeDetectionStrategy, Component, Input } from "@angular/core";
import type { PillVariant } from "./pill.component";

/** The old pill of the reports screen. A component of its own with its own inputs: it does not extend PillComponent. */
@Component({
    selector: "app-pill-legacy",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<span class="pill legacy" [class]="variant">{{ label }}@if (!disableTooltip) {<span class="hint">i</span>}</span>`
})
export class PillLegacyComponent {
    @Input() label = "";
    @Input() variant: PillVariant = "info";
    @Input() disableTooltip = false;
}
--- fancy ---
import { ChangeDetectionStrategy, Component, input } from "@angular/core";
import { PillComponent } from "./pill.component";

/** A pill with an icon in front. The label, the variant and the hint switch come from PillComponent. */
@Component({
    selector: "app-fancy-pill",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<span class="pill fancy" [class]="variant()"><i class="icon">{{ icon() }}</i>{{ label() }}@if (!disableTooltip()) {<span class="hint">i</span>}</span>`
})
export class FancyPillComponent extends PillComponent {
    readonly icon = input("star");
}
--- status ---
import { ChangeDetectionStrategy, Component, computed } from "@angular/core";
import { PillComponent } from "./pill.component";

/** A pill for a state of the screen: it reads its label out loud and marks the hint with a question mark. */
@Component({
    selector: "app-status-pill",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<span class="pill status" [class]="variant()" [attr.aria-label]="spoken()">{{ label() }}@if (!disableTooltip()) {<span class="hint">?</span>}</span>`
})
export class StatusPillComponent extends PillComponent {
    readonly spoken = computed(() => this.disableTooltip() ? this.label() : this.label() + ", a hint is available");
}

