import { readFileSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";

const TAGS = ["app-fancy-pill", "app-status-pill"];
const OLD = "disableTooltip";
const NEW = "hideHint";

const files = execSync('git ls-files "*.ts" "*.html"', { encoding: "utf8" })
    .split("\n").map(s => s.trim()).filter(Boolean);

let total = 0;
for (const file of files) {
    const src = readFileSync(file, "utf8");
    if (!src.includes(OLD)) continue;
    let out = "";
    let i = 0;
    let count = 0;
    while (i < src.length) {
        const next = TAGS
            .map(t => ({ t, idx: src.indexOf("<" + t, i) }))
            .filter(x => x.idx >= 0)
            .sort((a, b) => a.idx - b.idx)[0];
        if (!next) break;
        // the character after the tag name must end the name
        const after = src[next.idx + next.t.length + 1];
        if (!/[\s>/]/.test(after ?? "")) { out += src.slice(i, next.idx + 1); i = next.idx + 1; continue; }
        // find the end of the open tag, skipping quoted attribute values
        let j = next.idx + next.t.length + 1;
        let quote = null;
        while (j < src.length) {
            const c = src[j];
            if (quote) { if (c === quote) quote = null; }
            else if (c === '"' || c === "'") quote = c;
            else if (c === ">") break;
            j++;
        }
        const head = src.slice(i, next.idx);
        let tag = src.slice(next.idx, j);
        const before = tag;
        tag = tag.replace(new RegExp(`(?<=\\s)\\[${OLD}\\](?==)`, "g"), `[${NEW}]`);
        tag = tag.replace(new RegExp(`(?<=\\s)${OLD}(?=[\\s=>/]|$)`, "g"), NEW);
        if (tag !== before) count += (before.match(new RegExp(OLD, "g")) ?? []).length;
        out += head + tag;
        i = j;
    }
    out += src.slice(i);
    if (out !== src) {
        writeFileSync(file, out);
        total += count;
        console.log(`${file}: ${count}`);
    }
}
console.log("total bindings renamed:", total);

