cd "C:\Users\rafal\AppData\Local\Temp\rename-bench-skill-ng-OHeTJR\workspace" && node -e '
const {readFileSync,writeFileSync}=require("fs");
const {execSync}=require("child_process");
const re=/(fancyRef\.|pill\.|fancy\.|firstPill\(\)\??\.|fancy\(\)\??\.)disableTooltip/g;
let n=0,f=0;
for(const file of execSync("git ls-files \"*.ts\" \"*.html\"",{encoding:"utf8"}).split("\n").map(s=>s.trim()).filter(Boolean)){
  const s=readFileSync(file,"utf8");
  if(!s.includes("disableTooltip"))continue;
  const o=s.replace(re,(m,p)=>{n++;return p+"hideHint";});
  if(o!==s){writeFileSync(file,o);f++;}
}
console.log("replacements:",n,"files:",f);'

